package ru.neverland.mintespionage.service;
import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
/** Immutable purchase terms; no request identity is ever derived from a click or mutable config. */
public final class SpyPurchases {
    public static final int MAX=20000;
    public enum Kind{MISSION,NETWORK,DEFENSE}public enum Phase{PREPARED,PAID,APPLIED,REJECTED,CANCELLED,REFUND_PENDING,REFUNDED}
    public record Terms(UUID id,UUID town,String townName,UUID actor,String actorName,Kind kind,long cents,String reason,long created,UUID target,String targetName,String type,long duration,long cooldown,double success,double detection,int fromLevel){
        public Terms{Objects.requireNonNull(id);Objects.requireNonNull(town);Objects.requireNonNull(actor);Objects.requireNonNull(kind);text(townName,120);text(actorName,120);text(reason,240);if(cents<0||cents>100000000000L||created<0||fromLevel<0||fromLevel>10000)throw new IllegalArgumentException("Неверные условия покупки разведки");if(kind==Kind.MISSION){Objects.requireNonNull(target);text(targetName,120);text(type,80);if(target.equals(town)||!type.matches("[a-z0-9_-]+")||duration<1||duration>31536000000L||cooldown<0||cooldown>31536000000L||!Double.isFinite(success)||success<0||success>1||!Double.isFinite(detection)||detection<0||detection>1||fromLevel!=0)throw new IllegalArgumentException("Неверные условия миссии");}else if(target!=null||targetName!=null||type!=null||duration!=0||cooldown!=0||success!=0||detection!=0)throw new IllegalArgumentException("В улучшении найдены условия миссии");}
        public String fingerprint(){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(JSON.toJson(this).getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
    }
    public record Purchase(Terms terms,Phase phase,int refundAttempt){
        public Purchase(Terms terms,Phase phase){this(terms,phase,0);}public Purchase{Objects.requireNonNull(terms);Objects.requireNonNull(phase);if(refundAttempt<0||refundAttempt>1000||refundAttempt>0&&phase!=Phase.REFUND_PENDING&&phase!=Phase.REFUNDED)throw new IllegalArgumentException("Неверная попытка возврата");}
        public boolean pending(){return phase==Phase.PREPARED||phase==Phase.PAID||phase==Phase.REFUND_PENDING;}
        public Purchase phase(Phase next){if(next==phase)return this;if(!(phase==Phase.PREPARED&&(next==Phase.PAID||next==Phase.REJECTED||next==Phase.CANCELLED)||phase==Phase.PAID&&(next==Phase.APPLIED||next==Phase.REFUND_PENDING)||phase==Phase.REFUND_PENDING&&next==Phase.REFUNDED))throw new IllegalArgumentException("Нельзя повторить или обратить покупку");return new Purchase(terms,next,refundAttempt);}
        public UUID refundId(){return UUID.nameUUIDFromBytes(("espionage-refund:"+terms.id()+":"+refundAttempt).getBytes(StandardCharsets.UTF_8));}
        public Purchase rejectedRefund(){if(phase!=Phase.REFUND_PENDING)throw new IllegalArgumentException("Нет ожидающего возврата");return new Purchase(terms,phase,Math.incrementExact(refundAttempt));}
    }
    public record State(Map<UUID,Purchase> entries){public State{entries=Map.copyOf(entries);if(entries.size()>MAX)throw new IllegalArgumentException("Архив покупок заполнен");var pending=new HashSet<UUID>();for(var e:entries.entrySet()){var p=e.getValue();if(!e.getKey().equals(p.terms().id())||p.pending()&&!pending.add(p.terms().town()))throw new IllegalArgumentException("Повтор покупки или неверный ID");}}public static State empty(){return new State(Map.of());}public State put(Purchase p){var old=entries.get(p.terms().id());if(old!=null&&(!old.terms().equals(p.terms())||!(old.refundAttempt()==p.refundAttempt()?old.phase(p.phase()).equals(p):old.rejectedRefund().equals(p))))throw new IllegalArgumentException("Условия уже принятой покупки изменились");var copy=new HashMap<>(entries);copy.put(p.terms().id(),p);return new State(copy);}}
    static final com.google.gson.Gson JSON=new com.google.gson.GsonBuilder().disableHtmlEscaping().create();
    private static void text(String v,int max){if(v==null||v.isBlank()||v.length()>max||v.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Некорректное название покупки");}
    public static long cents(double amount){if(!Double.isFinite(amount)||amount<0)throw new IllegalArgumentException("Некорректная стоимость");long value=java.math.BigDecimal.valueOf(amount).movePointRight(2).longValueExact();if(value>100000000000L)throw new IllegalArgumentException("Слишком большая стоимость");return value;}
}
